<template>
  <div class="space-y-4" data-testid="storage-runtime">
    <div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-lg font-semibold">{{ t('storageGov.automation') }}</h2><UButton color="neutral" variant="outline" :loading="loading" @click="load">{{ t('storageGov.refresh') }}</UButton></div>
    <UAlert v-if="error" color="error" :title="t('storageGov.requestFailed')" :description="error" />
    <UAlert v-if="state && !state.configured" color="info" :title="t('storageGov.runtime.notConfigured')" :description="t('storageGov.runtime.setupHint')" />
    <template v-if="state?.configured">
      <UAlert v-if="state.problem || state.notification_problem" color="warning" :title="t('storageGov.runtime.needsAttention')" :description="reason(state.problem || state.notification_problem)" />
      <div class="flex flex-wrap items-center gap-3 text-sm"><span>{{ t(state.worker_enabled ? 'storageGov.runtime.workerReady' : 'storageGov.runtime.workerOff') }}</span><span>{{ t(state.admission_enabled ? 'storageGov.runtime.admissionOn' : 'storageGov.runtime.admissionOff') }}</span><span>{{ t(state.notifications_configured ? 'storageGov.runtime.notificationsOn' : 'storageGov.runtime.notificationsOff') }}</span></div>
      <div class="flex flex-wrap items-center gap-3 rounded-lg border border-default p-4"><p>{{ t('storageGov.runtime.available') }} {{ bytes(state.budget?.available_bytes) }}</p><p>{{ t('storageGov.runtime.reserved') }} {{ bytes(state.budget?.reserved_bytes) }}</p><UButton color="neutral" variant="outline" @click="openBudget">{{ t('storageGov.runtime.budget') }}</UButton><UButton color="neutral" variant="outline" @click="deliveryOpen = true">{{ t('storageGov.runtime.delivery') }}</UButton></div>
      <p class="text-sm text-muted">{{ t('storageGov.runtime.safetyHint') }}</p>
      <UAlert v-if="state.lifecycle?.runs.some(r => r.state === 'unconfirmed' && !r.acknowledged_at)" color="warning" :title="t('storageGov.runtime.needsAttention')"><template #actions><UButton color="neutral" @click="runsOpen = true">{{ t('storageGov.runtime.runs') }}</UButton></template></UAlert>
      <div v-if="state.lifecycle?.sources.length" class="overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr><th class="p-2">{{ t('storageGov.resource') }}</th><th class="p-2">{{ t('storageGov.state') }}</th><th class="p-2">{{ t('storageGov.runtime.retention') }}</th><th /></tr></thead><tbody><tr v-for="source in state.lifecycle.sources" :key="source.id"><td class="p-2">{{ source.name }}</td><td class="p-2">{{ source.supported ? t(policy(source.id)?.enabled ? 'storageGov.runtime.enabled' : 'storageGov.runtime.disabled') : t('storageGov.runtime.protectedSource') }}<p v-if="source.problem" class="text-warning">{{ reason(source.problem) }}</p></td><td class="p-2">{{ policy(source.id) ? `${policy(source.id)!.retention_days} ${t('storageGov.runtime.dayUnit')} / ${bytes(policy(source.id)!.max_bytes)}` : '—' }}</td><td class="p-2"><UButton :disabled="!source.supported || busy" color="neutral" variant="outline" @click="edit(source)">{{ t('storageGov.runtime.configure') }}</UButton></td></tr></tbody></table></div>
      <UButton color="neutral" variant="outline" @click="runsOpen = true">{{ t('storageGov.runtime.runs') }} · {{ state.lifecycle?.runs.length || 0 }}</UButton>
    </template>
    <UModal v-model:open="policyOpen" :title="selected?.name || t('storageGov.runtime.configure')" :description="t('storageGov.runtime.policyHint')" :dismissible="!busy" :close="!busy"><template #body><div class="space-y-4" data-testid="storage-runtime-policy">
      <UAlert v-if="error" color="error" :title="t('storageGov.requestFailed')" :description="error" />
      <UAlert v-if="!state?.lifecycle?.allow_enforce" color="warning" :title="t('storageGov.runtime.enforceOff')" />
      <UForm :schema="policySchema" :state="form" class="space-y-4" @submit="save">
        <div class="grid gap-3 sm:grid-cols-2"><UFormField :label="t('storageGov.runtime.days')" name="days"><UInput v-model="form.days" type="number" :disabled="busy" class="w-full" data-testid="runtime-days" /></UFormField><UFormField :label="t('storageGov.runtime.cap')" name="gib"><UInput v-model="form.gib" type="number" step="0.01" :disabled="busy" class="w-full" data-testid="runtime-budget" /></UFormField></div>
        <UCheckbox v-model="form.enabled" :disabled="busy || !state?.lifecycle?.allow_enforce || form.mode === 'disabled'" :label="t('storageGov.runtime.enablePolicy')" data-testid="runtime-enabled" />
        <UFormField :label="t('storageGov.archive.cleanupMode')" name="mode"><USelect v-model="form.mode" :items="cleanupModes" :disabled="busy" class="w-full" data-testid="runtime-cleanup-mode" /></UFormField>
        <p class="text-sm text-muted">{{ t('storageGov.archive.modeHint') }}</p>
        <UCheckbox v-model="confirmed" :disabled="busy" :label="t('storageGov.runtime.confirm')" data-testid="runtime-confirm" />
        <div class="flex flex-wrap gap-3"><UButton type="button" color="neutral" variant="outline" :loading="busy" @click="previewPolicy">{{ t('storageGov.logs.preview') }}</UButton><UButton type="submit" :loading="busy" :disabled="!confirmed" data-testid="runtime-save">{{ t('storageGov.runtime.save') }}</UButton></div>
      </UForm>
      <div v-if="preview" class="rounded border border-default p-3 text-sm" data-testid="runtime-preview"><p>{{ t('storageGov.runtime.candidates', { count: preview.candidate_names.length, bytes: bytes(preview.candidate_bytes) }) }}</p><p v-if="preview.over_budget" class="text-warning">{{ t('storageGov.runtime.overBudget') }}</p><ul class="mt-2 max-h-40 overflow-auto"><li v-for="name in preview.candidate_names" :key="name" class="break-all">{{ name }}</li></ul><details class="mt-2"><summary>{{ t('storageGov.logs.skipped') }}</summary><p v-for="(count, code) in preview.protected" :key="code">{{ reason(String(code)) }} · {{ count }}</p></details></div>
      <p v-if="saved" class="text-success" role="status">{{ t('storageGov.runtime.saved') }}</p>
      <UButton v-if="selected && policy(selected.id)?.enabled" color="error" variant="outline" :loading="busy" :disabled="attempted || !preview || isDirty" data-testid="runtime-run" @click="runOnce">{{ t('storageGov.runtime.runOnce') }}</UButton>
      <p v-if="result" :class="result.state === 'completed' ? 'text-success' : 'text-warning'">{{ t('storageGov.runtime.states.' + result.state) }} · {{ t('storageGov.logs.confirmedDeleted') }} {{ result.state === 'unconfirmed' || result.state === 'executing' ? '—' : result.deleted_files }}</p>
    </div></template></UModal>
    <UModal v-model:open="budgetOpen" :title="t('storageGov.runtime.budget')" :description="t('storageGov.runtime.sharedBudget')" :dismissible="!busy" :close="!busy"><template #body><div class="space-y-4" data-testid="storage-runtime-budget"><UAlert v-if="error" color="error" :title="t('storageGov.requestFailed')" :description="error" /><UForm :schema="budgetSchema" :state="budgetForm" class="space-y-4" @submit="saveBudget"><UFormField :label="t('storageGov.runtime.minimum')" name="minimum"><UInput v-model="budgetForm.minimum" type="number" class="w-full" /></UFormField><UFormField :label="t('storageGov.runtime.critical')" name="critical"><UInput v-model="budgetForm.critical" type="number" class="w-full" /></UFormField><UFormField :label="t('storageGov.runtime.maximum')" name="maximum"><UInput v-model="budgetForm.maximum" type="number" class="w-full" /></UFormField><UFormField :label="t('storageGov.runtime.concurrent')" name="concurrent"><UInput v-model="budgetForm.concurrent" type="number" class="w-full" /></UFormField><UCheckbox v-model="budgetConfirmed" :label="t('storageGov.runtime.confirmBudget')" /><UButton type="submit" :loading="busy" :disabled="!budgetConfirmed">{{ t('storageGov.runtime.save') }}</UButton></UForm><p v-if="saved" class="text-success">{{ t('storageGov.runtime.saved') }}</p><details><summary>{{ t('storageGov.runtime.reservations') }}</summary><ul><li v-for="lease in state?.budget?.active" :key="lease.id">{{ lease.instance_id }} · {{ bytes(lease.peak_bytes - lease.written_bytes) }} · {{ new Date(lease.expires_at).toLocaleString() }}</li></ul></details></div></template></UModal>
    <UModal v-model:open="deliveryOpen" :title="t('storageGov.runtime.delivery')" :description="t('storageGov.runtime.deliveryHint')"><template #body><dl v-if="state?.log_delivery" class="grid grid-cols-2 gap-3"><template v-for="key in ['delivered', 'failed', 'dropped', 'queued_entries', 'queued_bytes'] as const" :key="key"><dt>{{ t('storageGov.runtime.deliveryFields.' + key) }}</dt><dd>{{ key === 'queued_bytes' ? bytes(state.log_delivery[key]) : state.log_delivery[key] }}</dd></template></dl><p v-else>{{ t('storageGov.runtime.lokiOff') }}</p></template></UModal>
    <UModal v-model:open="runsOpen" :title="t('storageGov.runtime.runs')" :description="t('storageGov.runtime.runHint')" :ui="{ content: 'max-w-4xl' }"><template #body><div class="max-h-[65vh] overflow-auto"><table class="w-full text-left text-sm"><thead><tr><th class="p-2">{{ t('storageGov.resource') }}</th><th>{{ t('storageGov.state') }}</th><th>{{ t('storageGov.logs.confirmedDeleted') }}</th></tr></thead><tbody><tr v-for="run in state?.lifecycle?.runs.slice().reverse() || []" :key="run.id"><td class="p-2">{{ sourceName(run.source_id) }}<p class="text-muted">{{ new Date(run.started_at).toLocaleString() }}</p></td><td class="p-2">{{ t('storageGov.runtime.states.' + run.state) }}<p v-if="run.problem" class="text-warning">{{ reason(run.problem) }}</p></td><td>{{ run.state === 'unconfirmed' || run.state === 'executing' ? '—' : run.deleted_files }}<UButton v-if="run.state === 'unconfirmed' && !run.acknowledged_at" :disabled="busy || policy(run.source_id)?.enabled" color="neutral" variant="outline" @click="ackRun = run; ackConfirmed = false">{{ t('storageGov.runtime.acknowledge') }}</UButton></td></tr></tbody></table></div></template></UModal>
    <UModal :open="!!ackRun" :title="t('storageGov.runtime.acknowledge')" :description="t('storageGov.runtime.runHint')" :dismissible="!busy" :close="!busy" @update:open="value => { if (!value) ackRun = undefined }"><template #body><div class="space-y-4"><UCheckbox v-model="ackConfirmed" :label="t('storageGov.runtime.ackConfirm')" /><UAlert v-if="error" color="error" :title="error" /><UButton :disabled="!ackConfirmed" :loading="busy" @click="acknowledge">{{ t('storageGov.runtime.acknowledge') }}</UButton></div></template></UModal>
  </div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import * as v from 'valibot';
import { useStorageRuntimeService, type StorageRuntime, type RuntimeSource, type RuntimePreview, type RuntimeRun } from '~/composables/api/services/storageRuntimeService';
import { formatStorageBytes as bytes } from '~/utils/storage-capacity';
const props = defineProps<{ revision?: number }>(); const { t, te } = useI18n(); const api = useStorageRuntimeService(); const GiB = 1024 ** 3;
const state = ref<StorageRuntime>(), selected = ref<RuntimeSource>(), preview = ref<RuntimePreview>(), result = ref<RuntimeRun>();
const loading = ref(false), busy = ref(false), error = ref(''), saved = ref(false), confirmed = ref(false), budgetConfirmed = ref(false), attempted = ref(false);
const ackRun = ref<RuntimeRun>(), ackConfirmed = ref(false);
const editorRevision = ref(0);
const drafts = new Map<string, { revision: number; form: typeof form }>();
const policyOpen = ref(false), budgetOpen = ref(false), deliveryOpen = ref(false), runsOpen = ref(false);
const form = reactive({ days: 7 as string | number, gib: 1 as string | number, enabled: false, mode: 'disabled' as 'disabled' | 'expire_delete' | 'archive_then_delete' });
const budgetForm = reactive({ minimum: 20 as string | number, critical: 10 as string | number, maximum: 90 as string | number, concurrent: 1 as string | number });
let controller: AbortController | undefined, readController: AbortController | undefined, requestID = '';
const number = (min: number, max: number, integer = false) => v.pipe(v.union([v.string(), v.number()]), v.transform(Number), v.check(n => Number.isFinite(n) && n >= min && n <= max && (!integer || Number.isInteger(n)), t('storageGov.drafts.invalid')));
const policySchema = computed(() => v.pipe(v.object({ days: number(1, 3650, true), gib: number(1 / GiB, 1048576), enabled: v.boolean(), mode: v.picklist(['disabled', 'expire_delete', 'archive_then_delete']) }), v.check(value => !value.enabled || value.mode !== 'disabled', t('storageGov.drafts.invalid'))));
const budgetSchema = computed(() => v.pipe(v.object({ minimum: number(1 / GiB, 1048576), critical: number(1 / GiB, 1048576), maximum: number(0, 1048576), concurrent: number(1, 16, true) }), v.check(n => n.critical < n.minimum, t('storageGov.drafts.invalid'))));
const cleanupModes = computed(() => ['disabled', 'expire_delete', 'archive_then_delete'].map(value => ({ value, label: t('storageGov.archive.modes.' + value) })));
const policy = (id: string) => state.value?.lifecycle?.policies.find(p => p.source_id === id);
const sourceName = (id: string) => state.value?.lifecycle?.sources.find(s => s.id === id)?.name || id;
const reason = (code?: string) => te('storageGov.runtime.reasons.' + code) ? t('storageGov.runtime.reasons.' + code) : t('storageGov.runtime.reasons.unknown');
const isDirty = computed(() => { const p = selected.value && policy(selected.value.id); return !p || p.retention_days !== Number(form.days) || p.max_bytes !== Math.round(Number(form.gib) * GiB) || p.enabled !== form.enabled || p.cleanup_mode !== form.mode; });
async function load() { readController?.abort(); const r = readController = new AbortController(); loading.value = true; try { const value = await api.status(r.signal); if (!r.signal.aborted) state.value = value; } catch (e) { if (!r.signal.aborted) error.value = e instanceof Error ? e.message : t('storageGov.requestFailed'); } finally { if (!r.signal.aborted) loading.value = false; } }
function edit(source: RuntimeSource) { selected.value = source; const p = policy(source.id), draft = drafts.get(source.id); editorRevision.value = draft?.revision ?? p?.revision ?? 0; Object.assign(form, draft?.form || { days: p?.retention_days || 7, gib: (p?.max_bytes || GiB) / GiB, enabled: p?.enabled || false, mode: p?.cleanup_mode || 'disabled' }); confirmed.value = false; preview.value = undefined; result.value = undefined; attempted.value = false; requestID = ''; saved.value = false; error.value = ''; policyOpen.value = true; }
async function previewPolicy() { if (!selected.value || busy.value || !v.safeParse(policySchema.value, form).success) return; const r = controller = new AbortController(); busy.value = true; error.value = ''; try { const value = await api.preview(selected.value.id, Number(form.days), Math.round(Number(form.gib) * GiB), r.signal); if (!r.signal.aborted) preview.value = value; } catch (e) { if (!r.signal.aborted) error.value = e instanceof Error ? e.message : t('storageGov.requestFailed'); } finally { if (!r.signal.aborted) busy.value = false; } }
async function save() {
  if (!selected.value || busy.value || !confirmed.value || !v.safeParse(policySchema.value, form).success) return;
  const source = selected.value, revision = editorRevision.value, r = controller = new AbortController(); busy.value = true; saved.value = false; error.value = '';
  const body = { expected_revision: revision, enabled: form.enabled, retention_days: Number(form.days), max_bytes: Math.round(Number(form.gib) * GiB), cleanup_mode: form.mode, require_archive: form.mode === 'archive_then_delete', confirm: true as const };
  const readback = async () => { const value = await api.status(r.signal); const p = value.lifecycle?.policies.find(p => p.source_id === source.id); if (!p || p.revision !== revision + 1 || p.enabled !== body.enabled || p.retention_days !== body.retention_days || p.max_bytes !== body.max_bytes || p.require_archive !== body.require_archive || p.cleanup_mode !== body.cleanup_mode) throw new Error(t('storageGov.drafts.readbackFailed')); if (!r.signal.aborted) { state.value = value; editorRevision.value = p.revision; drafts.set(source.id, { revision: p.revision, form: { ...form } }); saved.value = true; confirmed.value = false; preview.value = undefined; } };
  try { await api.savePolicy(source.id, body, r.signal); await readback(); } catch (e) { if (!r.signal.aborted) { try { await readback(); } catch { error.value = e instanceof Error ? e.message : t('storageGov.requestFailed'); } } } finally { if (!r.signal.aborted) busy.value = false; }
}
async function runOnce() {
  const source = selected.value, p = source && policy(source.id); if (!source || !p?.enabled || !preview.value || busy.value || attempted.value || isDirty.value) return;
  const r = controller = new AbortController(); busy.value = true; attempted.value = true; requestID ||= crypto.randomUUID(); error.value = '';
  try { await api.run(source.id, p.revision, requestID, r.signal); const value = await api.status(r.signal); const run = value.lifecycle?.runs.find(row => row.request_key === requestID); if (!run) throw new Error(t('storageGov.logs.checkRecord')); if (!r.signal.aborted) { state.value = value; result.value = run; } } catch (e) { if (!r.signal.aborted) { error.value = e instanceof Error ? e.message : t('storageGov.logs.checkRecord'); try { const value = await api.status(r.signal); const run = value.lifecycle?.runs.find(row => row.request_key === requestID); if (run && !r.signal.aborted) { state.value = value; result.value = run; } } catch { /* 只读回；不重发执行。 */ } } } finally { if (!r.signal.aborted) busy.value = false; }
}
function openBudget() { const p = state.value?.budget_policy; if (!p) return; Object.assign(budgetForm, { minimum: p.min_free_bytes / GiB, critical: p.critical_free_bytes / GiB, maximum: p.max_used_bytes / GiB, concurrent: p.max_concurrent }); budgetConfirmed.value = false; saved.value = false; error.value = ''; budgetOpen.value = true; }
async function saveBudget() {
  const p = state.value?.budget_policy; if (!p || busy.value || !budgetConfirmed.value || !v.safeParse(budgetSchema.value, budgetForm).success) return;
  const r = controller = new AbortController(); busy.value = true; error.value = ''; saved.value = false;
  const body = { expected_revision: p.revision, min_free_bytes: Math.round(Number(budgetForm.minimum) * GiB), critical_free_bytes: Math.round(Number(budgetForm.critical) * GiB), max_used_bytes: Math.round(Number(budgetForm.maximum) * GiB), max_concurrent: Number(budgetForm.concurrent), confirm: true as const };
  const readback = async () => { const value = await api.status(r.signal), actual = value.budget_policy;
    if (!actual || actual.revision !== p.revision + 1 || actual.min_free_bytes !== body.min_free_bytes || actual.critical_free_bytes !== body.critical_free_bytes || actual.max_used_bytes !== body.max_used_bytes || actual.max_concurrent !== body.max_concurrent) throw new Error(t('storageGov.drafts.readbackFailed'));
    if (!r.signal.aborted) { state.value = value; saved.value = true; budgetConfirmed.value = false; }
  };
  try { await api.saveBudget(body, r.signal); await readback(); } catch (e) { if (!r.signal.aborted) { try { await readback(); } catch { error.value = e instanceof Error ? e.message : t('storageGov.requestFailed'); } } } finally { if (!r.signal.aborted) busy.value = false; }
}
async function acknowledge() {
  const run = ackRun.value; if (!run || busy.value || !ackConfirmed.value || policy(run.source_id)?.enabled) return;
  const r = controller = new AbortController(); busy.value = true; error.value = '';
  try { await api.acknowledge(run.id, r.signal); const value = await api.status(r.signal); if (!value.lifecycle?.runs.find(item => item.id === run.id)?.acknowledged_at) throw new Error(t('storageGov.logs.checkRecord')); if (!r.signal.aborted) { state.value = value; ackRun.value = undefined; } }
  catch (e) { if (!r.signal.aborted) error.value = e instanceof Error ? e.message : t('storageGov.requestFailed'); } finally { if (!r.signal.aborted) busy.value = false; }
}
watch(form, () => { if (selected.value && policyOpen.value) { drafts.set(selected.value.id, { revision: editorRevision.value, form: { ...form } }); saved.value = false; confirmed.value = false; preview.value = undefined; } }, { deep: true });
watch(() => props.revision, () => void load()); onMounted(load); onBeforeUnmount(() => { controller?.abort(); readController?.abort(); });
</script>
